import {saveNote,listNotes,deleteNote} from './vault.js';
import {convertFile,finishResult} from './converter.js';
import {speechChunks} from './narration.js';
const $=id=>document.getElementById(id);
const element=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
const sampleBlocks=[{kind:'heading',level:1,text:'가격과 수요량의 관계'},{kind:'table',rows:[['가격 (원)','수요량 (개)'],['1,000','300'],['2,000','200'],['3,000','100']]},{kind:'paragraph',text:'다른 조건이 일정할 때, 가격이 오르면 수요량이 감소한다.'},{kind:'heading',level:1,text:'조건과 연결'},{kind:'paragraph',text:'0 < x < 10\nx <= -2\n측정값은 3.14입니다.'},{kind:'paragraph',method:'연결선 구조',text:'수요 증가에서 가격 상승으로 화살표가 이어집니다.'}];
const sample=()=>finishResult('경제학개론_변환 예시',sampleBlocks,true,[],true);
let result=sample(),file=null,busy=false,controller,position=0,playing=false,paused=false,token=0;
const status=text=>$('status').textContent=text;
const error=(text='')=>{$('error').hidden=!text;$('error').textContent=text};
function mark(){document.querySelectorAll('.reading-entry.active').forEach(n=>n.classList.remove('active'));$(result.entries[position]?.id)?.classList.add('active');$('reading-position').textContent=`${position+1} / ${result.entries.length}개 문단`;}
function stop(reset=false){token++;window.speechSynthesis?.cancel();playing=false;paused=false;$('listen').firstElementChild.textContent='소리로 듣기';$('listen').setAttribute('aria-pressed','false');if(reset)position=0;mark()}
function speak(index=position){if(!window.speechSynthesis){error('음성 기능을 지원하지 않는 브라우저입니다. TXT 파일을 저장해 스크린리더로 읽어 주세요.');return}const voice=window.speechSynthesis.getVoices().find(v=>v.lang.startsWith('ko')&&v.localService);if(!voice){error('기기에 설치된 한국어 음성을 찾지 못했습니다. 한국어 음성을 설치하거나 스크린리더로 결과를 읽어 주세요.');return}stop();error();position=index;playing=true;const mine=++token;$('listen').firstElementChild.textContent='일시정지';$('listen').setAttribute('aria-pressed','true');let chunks=[],chunkIndex=0;const advance=()=>{if(mine!==token)return;if(position>=result.entries.length){position=0;stop();status('끝까지 읽었습니다.');return}if(!chunks.length){mark();$(result.entries[position].id)?.scrollIntoView({block:'nearest',behavior:'auto'});chunks=speechChunks(result.entries[position].text);chunkIndex=0}if(chunkIndex>=chunks.length){position++;chunks=[];advance();return}const u=new SpeechSynthesisUtterance(chunks[chunkIndex++]);u.voice=voice;u.lang='ko-KR';u.rate=Number($('speed').value);u.onend=advance;u.onerror=e=>{if(mine!==token)return;stop();if(!['canceled','interrupted'].includes(e.error))error('음성을 재생하지 못했습니다. 기기의 한국어 음성 설정을 확인해 주세요.')};window.speechSynthesis.speak(u)};advance()}
function renderSource(b,header){const wrap=element('div',undefined,'source-block');if(b.source)wrap.append(element('p',b.source,'source-location'));if(b.method)wrap.append(element('span',b.method,'method'));
 if(b.kind==='table'){const scroll=element('div',undefined,'table-wrap'),table=element('table');table.append(element('caption',b.title||'추출한 표'));const body=element('tbody');const hc=b.headerRows||(header?1:0);b.rows.forEach((row,r)=>{const tr=element('tr');row.forEach((value,c)=>{const a=b.grid?.[r]?.[c];if(a&&(a.r!==r||a.c!==c))return;const cell=element(r<hc?'th':'td',value||'빈 값');if(r<hc)cell.scope=a?.cs>1?'colgroup':'col';if(a){cell.rowSpan=a.rs;cell.colSpan=a.cs}tr.append(cell)});body.append(tr)});table.append(body);scroll.append(table);wrap.append(scroll)
 }else{if(b.preview){const image=element('img');image.src=b.preview;image.alt=`${b.source||'자료'} 원본 이미지`;image.loading='lazy';wrap.append(image)}if(b.layoutText)wrap.append(element('p',b.layoutText,'layout-description'));if(b.text)wrap.append(element(b.kind==='heading'?'h4':'p',b.kind==='visual'&&b.ocrText?b.ocrText:b.text))}return wrap}
function render(next,{reset=true}={}){stop();result=next;if(reset)position=0;position=Math.min(position,result.entries.length-1);$('document-name').textContent=next.name;$('result-badge').textContent=next.sample?'같은 엔진으로 변환한 예시':next.coverage.unresolved?'변환 완료 · 그림은 글자 중심':'변환 완료';$('result-badge').classList.toggle('complete',!next.sample);const c=next.coverage;$('coverage').textContent=[`표 ${c.tables}개`,`구조 기반 설명 ${c.structured}개`,...(c.visuals?[`시각 자료 ${c.visuals}개`,`글자 인식 ${c.ocr}개`,`배치 설명 ${c.layout||0}개`,...(c.unreadable?[`글자 없는 그림 ${c.unreadable}개`]:[])]:[])].join(' · ');
 $('source-content').replaceChildren(...next.blocks.map(b=>renderSource(b,next.headers)));const narrative=$('narrative-content');narrative.replaceChildren();const select=$('section-jump');select.replaceChildren(element('option','제목 선택'));select.firstChild.value='';next.entries.forEach((e,i)=>{const wrap=element('div',undefined,`reading-entry ${e.kind==='notice'?'notice':''}`);wrap.id=e.id;wrap.tabIndex=-1;if(e.method)wrap.append(element('span',e.method,'method'));wrap.append(element(e.kind==='heading'?`h${e.level}`:'p',e.text));const actions=element('div',undefined,'entry-actions');if(e.source)actions.append(element('span',e.source));const play=element('button','여기부터 듣기');play.setAttribute('aria-label',`여기부터 듣기: ${i+1}번째 문단`);play.addEventListener('click',()=>speak(i));actions.append(play);wrap.append(actions);narrative.append(wrap);if(e.kind==='heading'){const opt=element('option',e.text);opt.value=String(i);select.append(opt)}});mark()}
function choose(f){if(!f||busy)return;stop();error();if(f.size>20*1024*1024){error('20 MB 이하의 파일을 선택해 주세요.');return}if(!/\.(pdf|docx|pptx|csv|txt|md)$/i.test(f.name)){error('PDF, DOCX, PPTX, CSV, TXT, MD 파일을 선택해 주세요.');return}file=f;$('file-name').textContent=f.name;$('file-meta').textContent=`${(f.size/1024/1024).toFixed(2)} MB · 변환 준비 완료`;$('choose-label').textContent='다른 파일 선택 ↗';$('convert').disabled=false;status(`${f.name} 파일을 선택했습니다.`)}
function setBusy(value){const restoreFocus=!value&&$('progress-box').contains(document.activeElement);busy=value;$('convert').disabled=value||!file;$('vault-save').disabled=value;for(const id of ['file-input','first-header','ocr-enabled','sample-open'])$(id).disabled=value;$('progress-box').hidden=!value;$('convert').firstElementChild.textContent=value?'변환 중':'자료 변환하기';$('reading-workspace').setAttribute('aria-busy',String(value));if(restoreFocus)$('convert').focus()}
$('file-input').addEventListener('change',e=>choose(e.target.files[0]));$('dropzone').addEventListener('dragover',e=>{e.preventDefault();$('dropzone').classList.add('dragging')});$('dropzone').addEventListener('dragleave',()=>$('dropzone').classList.remove('dragging'));$('dropzone').addEventListener('drop',e=>{e.preventDefault();$('dropzone').classList.remove('dragging');choose(e.dataTransfer.files[0])});
$('convert').addEventListener('click',async()=>{if(!file||busy)return;stop();error();controller=new AbortController();setBusy(true);$('progress-text').textContent='문서 구조를 읽는 중';try{const next=await convertFile(file,$('first-header').checked,{signal:controller.signal,ocr:$('ocr-enabled').checked,progress:text=>$('progress-text').textContent=text});render(next);$('result-title').focus();status(`변환을 완료했습니다. ${next.entries.length}개 문단. ${next.coverage.unresolved?`그림은 추출된 글자와 배치를 중심으로 설명합니다.`:''}`)}catch(e){if(e.name==='AbortError')status('변환을 취소했습니다. 이전 결과를 유지합니다.');else error(e.message||'변환하지 못했습니다.')}finally{setBusy(false)}});
$('cancel').addEventListener('click',()=>{controller?.abort();$('progress-text').textContent='변환을 취소하고 있습니다.'});$('sample-open').addEventListener('click',()=>{error();render(sample());$('result-title').focus();status('예시를 같은 변환 방식으로 생성했습니다.')});
$('source-toggle').addEventListener('click',()=>{const hide=!$('source-pane').hidden;$('source-pane').hidden=hide;$('comparison').classList.toggle('reading-only',hide);$('source-toggle').setAttribute('aria-pressed',String(!hide));$('source-toggle').textContent=hide?'원문 구조 보기':'원문 구조 숨기기'});
$('section-jump').addEventListener('change',e=>{if(e.target.value==='')return;stop();position=Number(e.target.value);mark();$(result.entries[position].id).focus()});
$('listen').addEventListener('click',()=>{if(playing&&!paused){window.speechSynthesis.pause();paused=true;$('listen').firstElementChild.textContent='계속 듣기';$('listen').setAttribute('aria-pressed','false')}else if(playing&&paused){window.speechSynthesis.resume();paused=false;$('listen').firstElementChild.textContent='일시정지';$('listen').setAttribute('aria-pressed','true')}else speak()});$('stop').addEventListener('click',()=>stop(true));
for(const [id,delta]of [['previous',-1],['next',1]])$(id).addEventListener('click',()=>{const active=playing&&!paused;const next=Math.max(0,Math.min(result.entries.length-1,position+delta));stop();position=next;mark();if(active)speak(next);else $(result.entries[next].id).focus()});$('speed').addEventListener('change',()=>{if(playing&&!paused)speak(position);else if(paused)stop()});window.addEventListener('pagehide',()=>{stop();controller?.abort()});
const fullText=()=>result.entries.map(e=>`${e.source?e.source+'\n':''}${e.method?'['+e.method+']\n':''}${e.text}`).join('\n\n');
$('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(fullText());status('텍스트를 복사했습니다.');$('copy').firstElementChild.textContent='복사됨';setTimeout(()=>$('copy').firstElementChild.textContent='텍스트 복사',2000)}catch{error('복사 권한이 없습니다. TXT 저장을 이용해 주세요.')}});
$('download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob(['\ufeff',fullText()],{type:'text/plain;charset=utf-8'}));const a=element('a');a.href=url;a.download=`${result.name.replace(/\.[^.]+$/,'')}_리드온.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('텍스트 파일을 저장했습니다.')});
$('guide-open').addEventListener('click',()=>$('guide').showModal());$('guide-close').addEventListener('click',()=>$('guide').close());$('guide-done').addEventListener('click',()=>$('guide').close());render(result);
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'read_conversion',title:'변환 결과 읽기',description:'현재 문서의 서술형 텍스트, 변환 방법, 설명이 불완전한 자료 수를 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('빈 객체만 입력할 수 있습니다.');return{name:result.name,isExample:!!result.sample,processing:busy,paragraphs:result.paragraphs,warnings:result.warnings,coverage:result.coverage}}},{signal:lifecycle.signal})).catch(()=>{})}catch{}}

let saving=false,pendingNote;
async function refreshVault(){
 $('vault-status').textContent='보관함을 불러오는 중입니다.';$('vault-list').replaceChildren();
 try{const notes=await listNotes();$('vault-status').textContent=notes.length?`${notes.length}개의 저장된 노트${notes.length===100?' · 최근 100개 표시':''}`:'아직 저장한 노트가 없습니다.';
  for(const item of notes){const li=element('li'),info=element('div');info.append(element('strong',item.damaged?'열 수 없는 노트':item.note.name),element('span',new Date(item.createdAt).toLocaleString('ko-KR')));li.append(info);
   if(!item.damaged){const open=element('button','열기');open.setAttribute('aria-label',item.note.name+' 열기');open.addEventListener('click',()=>{if(busy){$('vault-status').textContent='변환이 끝난 뒤 열어 주세요.';return}const n=item.note;const entries=n.entries.map((e,i)=>({...e,id:'saved-'+i,level:Math.max(2,Math.min(6,Number(e.level)||2))}));render({...n,entries,blocks:[{kind:'paragraph',text:'보관함에는 변환된 텍스트만 저장됩니다. 원본 구조와 그림은 원본 파일을 다시 선택하면 볼 수 있습니다.'}],headers:true,sample:false,paragraphs:entries.map(e=>e.text),coverage:n.coverage||{tables:0,structured:0,visuals:0,ocr:0,layout:0,unresolved:0}});$('vault').close();$('result-title').focus();status('보관한 노트를 열었습니다.')});li.append(open)}
   const remove=element('button','삭제');remove.setAttribute('aria-label',(item.note?.name||'열 수 없는 노트')+' 삭제');let armed=false;remove.addEventListener('click',async()=>{if(!armed){armed=true;remove.textContent='삭제 확인';$('vault-status').textContent='삭제하면 되돌릴 수 없습니다. 같은 버튼을 한 번 더 누르면 삭제합니다.';return}remove.disabled=true;try{await deleteNote(item.id);await refreshVault()}catch(e){remove.disabled=false;$('vault-status').textContent=e.message}});li.append(remove);$('vault-list').append(li);
  }
 }catch(e){$('vault-status').textContent=e.message}
}
$('vault-open').addEventListener('click',()=>{$('vault-consent').hidden=true;$('vault').showModal();refreshVault()});
$('vault-close').addEventListener('click',()=>$('vault').close());$('vault-refresh').addEventListener('click',refreshVault);
$('vault-save').addEventListener('click',()=>{if(busy)return;pendingNote=result;$('vault-save-title').textContent=result.name;$('vault-consent').hidden=false;$('vault-list').replaceChildren();$('vault-status').textContent='';$('vault').showModal()});
$('vault-confirm').addEventListener('click',async()=>{if(saving||!pendingNote)return;saving=true;$('vault-confirm').disabled=true;$('vault-status').textContent='텍스트를 암호화해 저장하는 중입니다.';try{await saveNote(pendingNote);$('vault-consent').hidden=true;status('보관함에 저장했습니다.');await refreshVault()}catch(e){$('vault-status').textContent=e.message}finally{saving=false;$('vault-confirm').disabled=false}});
